import { Component, OnInit } from '@angular/core';
import { WeaponService } from '../../service/weapon.service';
import { ActivatedRoute, Router } from '@angular/router';
import { WeaponForm } from '../../model/weapon-form';
import { WeaponTypeService } from "../../../weaponType/service/weaponType.service";
import { WeaponTypes } from "../../../weaponType/model/weaponTypes";

@Component({
  selector: 'app-weapon-edit',
  templateUrl: './weapon-edit.component.html',
  styleUrls: ['./weapon-edit.component.css']
})
export class WeaponEditComponent implements OnInit {
  uuid: string | undefined;
  weapon: WeaponForm | undefined;
  original: WeaponForm | undefined;
  weaponTypes: WeaponTypes | undefined;

  constructor(
    private weaponService: WeaponService,
    private weaponTypeService: WeaponTypeService,
    private route: ActivatedRoute,
    private router: Router
  ) {
  }

  ngOnInit() {
    this.route.params.subscribe(params => {
      this.weaponTypeService.getWeaponTypes()
        .subscribe(weaponTypes => this.weaponTypes = weaponTypes);

      this.weaponService.getWeapon(params['uuid'])
        .subscribe(weapon => {
          this.uuid = weapon.id;
          this.weapon = {
            name: weapon.name,
            description: weapon.description,
            damage: weapon.damage,
            range: weapon.range,
            weaponTypeId: weapon.weaponTypeId
          };
          this.original = {...this.weapon};
        });
    });
  }

  onSubmit(): void {
    this.weaponService.putWeapon(this.uuid!, this.weapon!)
      .subscribe(() => this.router.navigate(['/wea']));
  }
}
<article *ngIf="weapon">
  <header><h2>Edit weapon</h2></header>

  <form class="container"  #form="ngForm" (ngSubmit)="onSubmit()">
    <div class="row">
      <div class="col-4 p-2">
        <div>
          <label for="name">Name:</label>
          <input id="name" name="name" [(ngModel)]="weapon.name"/>
        </div>
      </div>
    </div>

    <div class="row">
      <div class="col-4 p-2">
        <div>
          <label for="description">Description:</label>
          <input id="description" name="description" [(ngModel)]="weapon.description"/>
        </div>
      </div>
    </div>

    <div class="row">
      <div class="col-4 p-2">
        <div>
          <label for="damage">Damage:</label>
          <textarea id="damage" name="damage" [(ngModel)]="weapon.damage"></textarea>
        </div>
      </div>
    </div>

    <div class="row">
      <div class="col-4 p-2">
        <div>
          <label for="range">Range:</label>
          <input id="range" name="range" [(ngModel)]="weapon.range"/>
        </div>
      </div>
    </div>

    <div class="row">
      <div class="col-2 p-2">
        <button type="submit">Update</button>
      </div>
      <div class="col-2 p-2">
        <button type="button" (click)="form.resetForm(original)">Reset</button>
      </div>
    </div>
  </form>
</article>
